<script lang="ts">
  import {onDestroy,onMount,untrack} from 'svelte';
  import {loadBooks,listBook,bookCommand,journalDetail,type BookConfiguration,type BookRow,type BookList,type BookPage,type BookAction,type BookCommand,type BookLine,type BookSource,type JournalDetail} from '../api/books';
  import {accessToken,ApiError} from '../api/client';
  import {operationUid} from '../api/operation';
  import {journalTotals} from '../util/bookAmounts';
  import {focusDialog} from '../util/focusDialog';
  import {requestConfirmation} from '../confirmation';
  let {moduleUid,moduleName='Module',revision=0,source=null,inline=false,initialTab,title='Operational books',onOpenChange=()=>{}}:{moduleUid:string;moduleName?:string;revision?:number;source?:BookSource|null;inline?:boolean;initialTab?:BookList;title?:string;onOpenChange?:(open:boolean)=>void}=$props();
  let config=$state<BookConfiguration|null>(null);let configError=$state('');let open=$state(false);let busy=$state(false);let loading=$state(false);let error=$state('');let notice=$state('');
  let tab=$state<BookList>('journals');let data=$state<BookPage|null>(null);let after=$state(0);let previous=$state<number[]>([]);let generation=0;let dead=false;let controller:AbortController|undefined;let configController:AbortController|undefined;
  let accounts=$state<BookRow[]>([]);let items=$state<BookRow[]>([]);let accountCursor=$state<number|null>(null);let itemCursor=$state<number|null>(null);let catalogBusy=$state(false);
  let form=$state<''|'journal'|'stock'|'account'|'item'|'reverse'|'reservation'>('');let date=$state(today());let explanation=$state('');let code=$state('');let name=$state('');let category=$state('asset');let unit=$state('');let itemUid=$state('');let movement=$state('receive');let quantity=$state('');let targetUid=$state('');let reservationAction=$state('release');
  let lines=$state<BookLine[]>([{account_uid:'',debit:'',credit:''},{account_uid:'',debit:'',credit:''}]);let detail=$state<JournalDetail|null>(null);let pending=$state<BookCommand|null>(null);
  const totals=$derived(journalTotals(lines,config?.settings.money_decimals??2));
  const sourceRequired=$derived(!!config?.settings.required_stage&&!source);
  const tabs=$derived(({journals:'Journals',accounts:'Accounts & balances',items:'Stock balances',reservations:'Reservations','stock-events':'Stock history'} as const));
  function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  function storageKey(){try{const payload=accessToken().split('.')[1];const actor=JSON.parse(atob(payload.replace(/-/g,'+').replace(/_/g,'/'))).uid;return `mx-book-pending:${actor}:${moduleUid}`;}catch{return '';}}
  function persist(value:BookCommand|null){const key=storageKey();if(!key)throw Error('Your account session is unavailable. Sign in again before posting.');if(value){const existing=sessionStorage.getItem(key);if(existing&&JSON.parse(existing).operation_uid!==value.operation_uid)throw Error('Another unconfirmed operation is retained for this book. Reopen Books and reconcile it first.');sessionStorage.setItem(key,JSON.stringify(value));}else sessionStorage.removeItem(key);}
  onMount(()=>{try{const raw=sessionStorage.getItem(storageKey());if(raw){pending=JSON.parse(raw);notice='An unconfirmed book operation was recovered in this tab. Retry the same operation to reconcile it before entering another.';}}catch{configError='The browser could not restore pending book operations. Check book history before entering another operation.';}});
  $effect(()=>{moduleUid;revision;untrack(()=>void availability());});
  onDestroy(()=>{dead=true;generation++;controller?.abort();configController?.abort();});
  async function availability(){configController?.abort();const request=new AbortController();configController=request;try{const next=await loadBooks(moduleUid,request.signal);if(!dead&&!request.signal.aborted){config=next;configError='';if(inline&&!open&&next.can_operate&&next.revision>0)await show();if(!next.can_operate){open=false;data=null;detail=null;accounts=[];items=[];}}}catch(e){if(!dead&&!request.signal.aborted)configError=e instanceof Error?e.message:String(e);}}
  async function reload(){controller?.abort();const request=new AbortController();controller=request;const current=++generation;loading=true;error='';try{const result=await listBook(moduleUid,tab,after,request.signal);if(!dead&&current===generation)data=result;}catch(e){if(!dead&&!request.signal.aborted)error=e instanceof Error?e.message:String(e);}finally{if(current===generation)loading=false;}}
  async function catalogs(kind:'accounts'|'items',more=false){catalogBusy=true;try{const result=await listBook(moduleUid,kind,more?(kind==='accounts'?accountCursor:itemCursor)||0:0);if(dead)return;if(kind==='accounts'){accounts=more?[...accounts,...result.items]:result.items;accountCursor=result.next_cursor;}else{items=more?[...items,...result.items]:result.items;itemCursor=result.next_cursor;}}catch(e){error=e instanceof Error?e.message:String(e);}finally{catalogBusy=false;}}
  async function show(){try{const raw=sessionStorage.getItem(storageKey());if(raw)pending=JSON.parse(raw);}catch{error='Pending operation recovery failed. Check book history before posting.';}open=true;onOpenChange(true);tab=initialTab||(config?.settings.accounting?'journals':'items');previous=[];after=0;form='';detail=null;await reload();}
  function close(){if(busy||pending){error='This operation has not been acknowledged. Use Retry same operation before closing; do not create a second posting.';return;}open=false;onOpenChange(false);controller?.abort();generation++;loading=false;}
  async function choose(next:BookList){if(busy||pending)return;if(form&&!await requestConfirmation({title:'Discard this unposted entry?',description:'No posting has been submitted. Your current form will be cleared.',confirmLabel:'Discard entry',tone:'danger'}))return;tab=next;previous=[];after=0;form='';detail=null;await reload();}
  async function begin(next:typeof form,row?:BookRow){if(pending||busy)return;form=next;detail=null;explanation='';code='';name='';unit='';quantity='';itemUid=row?.uid||'';date=today();targetUid=row?.uid||'';lines=[{account_uid:'',debit:'',credit:''},{account_uid:'',debit:'',credit:''}];error='';notice='';if(next==='journal')await catalogs('accounts');if(next==='stock')await catalogs('items');}
  async function view(row:BookRow){if(busy||pending)return;loading=true;error='';try{const result=await journalDetail(moduleUid,row.uid);if(!dead&&open)detail=result;}catch(e){if(!dead)error=e instanceof Error?e.message:String(e);}finally{if(!dead)loading=false;}}
  function action():BookAction|null{
    if(form==='account')return {kind:'account',code,name,category};if(form==='item')return {kind:'item',code,name,unit};
    if(form==='journal')return {kind:'journal',date,description:explanation,source,lines:structuredClone($state.snapshot(lines))};
    if(form==='stock')return {kind:'stock',item_uid:itemUid,movement,quantity,note:explanation,source};
    if(form==='reverse')return {kind:'reverse',journal_uid:targetUid,date,reason:explanation};
    if(form==='reservation')return {kind:'reservation',reservation_uid:targetUid,action:reservationAction,note:explanation};return null;
  }
  async function submit(event:SubmitEvent){event.preventDefault();if(!config||pending||busy)return;const next=action();if(!next)return;
    if(next.kind==='journal'&&!totals?.balanced){error='Debits and credits must balance exactly. Use one positive amount per line and leave the other side blank.';return;}
    if(!await requestConfirmation({title:next.kind==='journal'?'Post this balanced journal?':next.kind==='reverse'?'Post a reversing journal?':next.kind==='stock'?'Confirm this stock operation?':next.kind==='reservation'?'Finish this stock reservation?':'Create this book definition?',description:'MX records the operator and immutable audit evidence. Posted transactions cannot be edited or deleted. Check amounts and the source record before confirming.',confirmLabel:'Confirm operation',tone:'primary'}))return;
    const request={...next,operation_uid:operationUid(),configuration_revision:config.revision};try{persist(request);pending=request;}catch(e){error=`${e instanceof Error?e.message:'This browser cannot retain the retry receipt. Enable site storage before posting.'} Nothing was submitted.`;return;}await sendPending();
  }
  async function sendPending(){if(!pending||busy)return;busy=true;error='';notice='';try{const result=await bookCommand(moduleUid,$state.snapshot(pending));
      // Acknowledged means committed, not merely queued or prepared in this browser.
      pending=null;form='';detail=null;try{persist(null);}catch{notice='Committed to MX; this tab could not clear its retry receipt. Replaying it is safe.';}
      notice=result.replayed?'Previously committed operation confirmed.':'Committed to MX.';after=0;previous=[];await reload();await availability();
    }catch(e){error=e instanceof Error?e.message:String(e);if(e instanceof ApiError&&[400,403,404,409,422].includes(e.status)){pending=null;try{persist(null);}catch{}await availability();}else{error+=' The result is unconfirmed. Retry this exact operation; MX will not post it twice.';}}finally{busy=false;}
  }
  function back(){if(!previous.length)return;after=previous.pop()!;void reload();}function next(){if(!data?.next_cursor)return;previous.push(after);after=data.next_cursor;void reload();}
  function leaving(event:BeforeUnloadEvent){if(pending||busy){event.preventDefault();event.returnValue='';}}
</script>
<svelte:window onbeforeunload={leaving}/>
{#if !inline}{#if config?.can_operate&&(config.revision>0)}<button class="button" type="button" onclick={show}>{pending?'Books · unconfirmed operation':'Books'}</button>{:else if configError}<button class="button" type="button" title={configError} onclick={availability}>Retry book availability</button>{/if}{/if}
{#snippet contents()}
  <header><div><p class="eyebrow">{moduleName}{source?' · Saved record':''}</p><h2 id="book-title">{title}</h2><p>Exact amounts · Confirmed postings · Preserved history</p></div>{#if !inline}<button class="button" type="button" disabled={busy||!!pending} onclick={close}>Close books</button>{/if}</header>
  <nav aria-label="Book sections">{#each Object.entries(tabs) as [key,label]}<button class="button" class:primary={tab===key} type="button" aria-pressed={tab===key} disabled={busy||!!pending} onclick={()=>choose(key as BookList)}>{label}</button>{/each}</nav>
  <div class="book-body" aria-busy={busy}>
    {#if error}<p class="notice error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
    {#if pending}<section class="pending"><h3>{busy?'Waiting for MX acknowledgement…':'Operation needs confirmation'}</h3><p>{pending.kind==='journal'?`${pending.description} · ${pending.lines.length} journal lines`:pending.kind==='stock'?`${pending.movement} ${pending.quantity} · ${pending.note}`:pending.kind==='reverse'?pending.reason:pending.kind==='reservation'?`${pending.action} · ${pending.note}`:pending.name}</p><p>Receipt: {pending.operation_uid}. Retry sends the original entries, not a new posting.</p><button class="button primary" type="button" disabled={busy} onclick={sendPending}>Retry same operation</button></section>{/if}
    {#if sourceRequired&&!pending}<p class="notice">New postings require an approved source record. Open that record in View mode and use its Books button. Existing history, reversals and reservation decisions remain available here.</p>{/if}
    {#if !form&&!pending}<div class="book-actions"><button class="button" type="button" disabled={loading} onclick={reload}>Refresh book</button>{#if tab==='journals'&&config?.settings.accounting}<button class="button primary" type="button" disabled={sourceRequired} onclick={()=>begin('journal')}>New journal</button>{/if}{#if (tab==='items'||tab==='stock-events')&&config?.settings.inventory}<button class="button primary" type="button" disabled={sourceRequired} onclick={()=>begin('stock')}>Stock operation</button>{/if}{#if tab==='accounts'&&config?.can_configure&&config.settings.accounting}<button class="button" type="button" onclick={()=>begin('account')}>Add account</button>{/if}{#if tab==='items'&&config?.can_configure&&config.settings.inventory}<button class="button" type="button" onclick={()=>begin('item')}>Add stock item</button>{/if}</div>{/if}
    {#if form}<form onsubmit={submit}><fieldset disabled={busy||!!pending}><legend>{form==='journal'?'New balanced journal':form==='stock'?'Receive, issue or reserve stock':form==='account'?'Add chart account':form==='item'?'Add stock item':form==='reverse'?'Reverse posted journal':'Finish reservation'}</legend>
      {#if form==='account'||form==='item'}<div class="entry-grid"><label>Code<input required maxlength="40" bind:value={code}/></label><label>Name<input required maxlength="120" bind:value={name}/></label>{#if form==='account'}<label>Category<select bind:value={category}>{#each ['asset','liability','equity','income','expense'] as type}<option value={type}>{type}</option>{/each}</select></label>{:else}<label>Unit<input required maxlength="40" placeholder="e.g. ream, piece, kilogram" bind:value={unit}/></label>{/if}</div>
      {:else}
        {#if form==='journal'||form==='reverse'}<label>Posting date<input type="date" required bind:value={date}/></label>{/if}
        {#if form==='journal'||form==='stock'}<p class="notice">{source?`Source: saved record revision ${source.record_revision}. MX verifies it before committing.`:config?.settings.required_stage?'A source record is required. Cancel this form, open the approved record, then use its Books button.':'Manual entry. To attach a record snapshot, open the saved record and use its Books button.'}</p>{/if}
        {#if form==='journal'}<p>Currency: <strong>{config?.settings.currency}</strong>. One debit OR credit per line; leave the other side blank.</p><div class="journal-lines">{#each lines as line,index}<div class="journal-line"><label>Account {index+1}<select required bind:value={line.account_uid}><option value="">Choose account…</option>{#each accounts as account}<option value={account.uid}>{account.code} · {account.name}</option>{/each}</select></label><label>Debit<input inputmode="decimal" bind:value={line.debit} placeholder="Blank if credit"/></label><label>Credit<input inputmode="decimal" bind:value={line.credit} placeholder="Blank if debit"/></label><button class="button" type="button" aria-label={`Remove line ${index+1}`} disabled={lines.length<=2} onclick={()=>lines=lines.filter((_,i)=>i!==index)}>Remove</button></div>{/each}</div><div class="book-actions"><button class="button" type="button" disabled={lines.length>=100} onclick={()=>lines.push({account_uid:'',debit:'',credit:''})}>Add line</button>{#if accountCursor}<button class="button" type="button" disabled={catalogBusy} onclick={()=>catalogs('accounts',true)}>Load more accounts</button>{/if}</div><p role="status">{totals?`Debit ${totals.debit} · Credit ${totals.credit} · ${totals.balanced?'Balanced':'Not balanced'}`:'Enter one valid positive amount per line.'}</p>
        {:else if form==='stock'}<div class="entry-grid"><label>Item<select required bind:value={itemUid}><option value="">Choose item…</option>{#each items as item}<option value={item.uid}>{item.code} · {item.name} · {item.available} available {item.unit}</option>{/each}</select></label><label>Operation<select bind:value={movement}><option value="receive">Receive — increase stock</option><option value="issue">Issue — use unreserved stock</option><option value="reserve">Reserve — hold available stock</option></select></label><label>Quantity<input required inputmode="decimal" bind:value={quantity}/></label></div>{#if itemCursor}<button class="button" type="button" disabled={catalogBusy} onclick={()=>catalogs('items',true)}>Load more items</button>{/if}
        {:else if form==='reservation'}<label>Decision<select bind:value={reservationAction}><option value="release">Release — return hold to available stock</option>{#if config?.settings.inventory}<option value="consume">Consume — issue held stock</option>{/if}</select></label>{/if}
        <label>{form==='reverse'?'Reason for reversal':'Explanation'}<textarea required rows="3" maxlength="900" bind:value={explanation}></textarea></label>
      {/if}
      <div class="book-actions"><button class="button primary" type="submit" disabled={busy||catalogBusy||!!pending}>{busy?'Waiting for MX…':'Review & confirm'}</button><button class="button" type="button" onclick={()=>{form='';error='';}}>Cancel unposted entry</button></div>
    </fieldset></form>{/if}
    {#if detail}<section class="journal-detail"><h3>Journal · {detail.date}</h3><p>{detail.description}</p><p>Posted by {detail.actor_name||detail.actor_uid}{detail.reversal_of?' · Reverses an earlier journal':''}</p><div class="table-wrap"><table><thead><tr><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody>{#each detail.lines as line}<tr><td>{line.code} · {line.name}</td><td>{line.debit}</td><td>{line.credit}</td></tr>{/each}</tbody></table></div><details><summary>Posting evidence</summary><p>Journal ID: {detail.uid}</p><p>Operator ID: {detail.actor_uid}</p>{#if detail.source_uid}<p>Saved source snapshot: {detail.snapshot_uid}</p><a class="button" href={`#module/${encodeURIComponent(moduleUid)}?record=${encodeURIComponent(detail.source_uid)}`} onclick={close}>Open source record</a><small>Use the record’s History to inspect the book.posted snapshot, not just its current values.</small>{/if}</details></section>{/if}
    {#if !form}<div class="book-table table-wrap"><table><thead><tr><th>{tab==='journals'?'Posting':'Item / account'}</th>{#if tab==='accounts'}<th>Debit</th><th>Credit</th><th>Net debit − credit</th>{:else if tab==='items'}<th>On hand</th><th>Reserved</th><th>Available</th>{:else if tab==='reservations'}<th>Quantity</th><th>Status</th>{:else if tab==='stock-events'}<th>Operation</th><th>Quantity</th><th>After: on hand / reserved</th>{/if}<th>Details</th></tr></thead><tbody>{#each data?.items||[] as row}<tr><td><strong>{row.code||row.date}</strong><span>{row.name||row.description}</span>{#if row.note}<small>{row.note}</small>{/if}</td>{#if tab==='accounts'}<td>{row.debit}</td><td>{row.credit}</td><td>{row.balance}</td>{:else if tab==='items'}<td>{row.on_hand} {row.unit}</td><td>{row.reserved}</td><td>{row.available}</td>{:else if tab==='reservations'}<td>{row.quantity}</td><td>{row.status}</td>{:else if tab==='stock-events'}<td>{row.movement}</td><td>{row.quantity}</td><td>{row.on_hand} / {row.reserved}</td>{/if}<td>{#if tab==='journals'}<button class="button" type="button" disabled={busy||!!pending} onclick={()=>view(row)}>View journal</button>{#if !row.reversal_of&&!row.reversed_by&&config?.settings.accounting}<button class="button" type="button" disabled={busy||!!pending} onclick={()=>begin('reverse',row)}>Reverse</button>{:else}<small>{row.reversal_of?'Reversal':'Reversed'}</small>{/if}{:else if tab==='reservations'&&row.status==='held'}<button class="button" type="button" disabled={busy||!!pending} onclick={()=>begin('reservation',row)}>Release / consume</button>{:else}<small>{row.category||row.actor_uid||'Exact balance'}</small>{/if}</td></tr>{/each}</tbody></table></div>{#if loading}<p role="status">Loading book…</p>{:else if !data?.items.length}<p class="empty-state compact">No entries in this book section. Nothing is generated automatically.</p>{/if}{/if}
  </div><footer><small>40 entries per page · {config?.settings.currency||'Stock quantities'} · Ordinary record edits never change posted balances</small><div><button class="button" type="button" disabled={loading||busy||!!pending||!!form||!previous.length} onclick={back}>Previous</button><button class="button" type="button" disabled={loading||busy||!!pending||!!form||!data?.has_next} onclick={next}>Next</button></div></footer>
{/snippet}
{#if inline}
 {#if configError}<p class="notice error" role="alert">{configError}<button class="button" onclick={availability}>Retry book availability</button></p>
 {:else if config&&!config.can_operate}<div class="empty-state"><h2>Book access restricted</h2><p>Your account does not have whole-book access. You can still use the other permitted module views.</p></div>
 {:else if open}<section class="book-dialog inline-book" aria-label={title}>{@render contents()}</section>
 {:else}<p role="status">Loading workspace book…</p>{/if}
{:else if open}<div class="overlay book-overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget)close();}}><div class="dialog book-dialog" role="dialog" aria-modal="true" aria-labelledby="book-title" tabindex="-1" use:focusDialog onkeydown={e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}}}>{@render contents()}</div></div>{/if}
<style>
  .inline-book.book-dialog{width:100%;height:auto;max-height:none;border:1px solid var(--line);border-radius:.8rem;background:var(--surface)}.inline-book>.book-body{overflow:visible}.inline-book>header{padding:1.1rem}.inline-book>nav{overflow:auto;flex-wrap:nowrap}.inline-book>nav .button{flex-shrink:0;white-space:nowrap}
  .book-overlay{z-index:160}.book-dialog{width:min(76rem,100%);max-height:calc(100dvh - 2rem);padding:0;display:flex;flex-direction:column;overflow:hidden}.book-dialog>header{padding:1rem;display:flex;justify-content:space-between;align-items:start;gap:1rem;border-bottom:1px solid var(--line)}h2{font-size:1.2rem;margin:.2rem 0}h3{font-size:1rem}header p{margin:.2rem 0;color:var(--muted)}nav,.book-actions{display:flex;flex-wrap:wrap;gap:.5rem}nav{padding:.75rem 1rem;border-bottom:1px solid var(--line)}.book-body{padding:1rem;min-height:0;overflow:auto}.book-actions{margin-bottom:1rem}.book-table{margin-top:1rem}.table-wrap{overflow:auto;max-width:100%}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:.75rem;overflow-wrap:anywhere;min-width:7rem}td span,td small{display:block;margin-top:.3rem}td button{margin:.2rem}small{font-size:.875rem;color:var(--muted)}fieldset{min-width:0;margin:1rem 0;padding:1rem;border:1px solid var(--line);border-radius:.6rem}legend{font-weight:650;padding:0 .5rem}.entry-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}label{display:grid;gap:.4rem;margin-bottom:1rem}input,textarea,select{width:100%;min-width:0;box-sizing:border-box}.journal-line{display:grid;grid-template-columns:minmax(12rem,2fr) repeat(2,minmax(7rem,1fr)) auto;gap:.65rem;align-items:center}.journal-line button{margin-bottom:1rem}.journal-lines{margin:1rem 0}.pending,.journal-detail{padding:1rem;border:1px solid var(--line);border-radius:.6rem;margin:1rem 0;overflow-wrap:anywhere}footer{padding:.75rem 1rem;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:.75rem;flex-wrap:wrap}footer>div{display:flex;gap:.5rem}@media(max-width:700px){.entry-grid,.journal-line{grid-template-columns:1fr}.journal-line{padding:.65rem;border:1px solid var(--line);border-radius:.5rem}.book-dialog{max-height:calc(100dvh - .75rem)}nav .button{flex-grow:1}}
  /* Keep the data usable with narrow screens and enlarged personal text. */
  .book-dialog>header,nav,footer{flex-shrink:0}
  .book-body{flex:1}
  @media(max-width:700px){
    .book-overlay{padding:.375rem}
    .book-dialog{height:calc(100dvh - .75rem)}
    .book-dialog>header{padding:.65rem;align-items:center}
    .book-dialog>header p{display:none}
    .book-dialog>header h2{font-size:1rem}
    nav{flex-wrap:nowrap;overflow-x:auto;padding:.5rem;gap:.4rem}
    nav .button{flex:0 0 auto;white-space:nowrap}
    footer{padding:.5rem}
    footer>small{display:none}
    footer>div{margin-left:auto}
  }
</style>
